func printDryRun(cmd *cobra.Command, opType string, opName string, vars map[string]any) error {
	fmt.Fprintf(os.Stderr, "[dry-run] %s %s\n", opType, opName)
	data, _ := json.MarshalIndent(vars, "", "  ")
	fmt.Fprintf(os.Stdout, "%s\n", data)
	return nil
}
